import networkx as nx

def get_diamond_cells(r):
    cells = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if abs(x) + abs(y) <= r:
                cells.append((x, y))
    return cells

def min_perimeter(cells):
    # The minimal perimeter of a set of cells is 4 * (max_x - min_x + 1)
    # wait, that's for a rectangle.
    # For any set of cells, the minimal perimeter is 2 * (width + height)
    # if it's "convex" in the grid sense.
    min_x = min(c[0] for c in cells)
    max_x = max(c[0] for c in cells)
    min_y = min(c[1] for c in cells)
    max_y = max(c[1] for c in cells)
    return 2 * ((max_x - min_x + 1) + (max_y - min_y + 1))

for r in range(0, 5):
    cells = get_diamond_cells(r)
    print(f"r={r}, perimeter={min_perimeter(cells)}")
